// Attach `classes` to each concept from CONCEPT_CLASSES (single source of truth) and freeze.
const CLASS_OF = new Map();
for (const k of CONCEPT_CLASSES) for (const m of k.members) {
  if (!CLASS_OF.has(m)) CLASS_OF.set(m, []);
  CLASS_OF.get(m).push(k.slug);
}

export const CONCEPTS_REGISTRY = Object.freeze(RAW_CONCEPTS.map((x) => Object.freeze({
  ...x,
  aliases: Object.freeze([...x.aliases]),
  related: Object.freeze([...x.related]),
  sources: Object.freeze([...x.sources]),
  classes: Object.freeze([...(CLASS_OF.get(x.slug) || [])]),
})));

const BY_SLUG = new Map(CONCEPTS_REGISTRY.map((x) => [x.slug, x]));

const norm = (s) => String(s).normalize('NFC').trim().toLowerCase();

/**
 * Text-matching index: one row per (term or alias), sorted longest-first so that a scanner
 * matching greedily prefers "de Bruijn–Newman constant Λ" over "Λ".
 */
export const ALIAS_INDEX = Object.freeze(
  CONCEPTS_REGISTRY
    .flatMap((x) => [x.term, ...x.aliases].map((alias) => ({ alias, key: norm(alias), slug: x.slug })))
    .filter((row, i, arr) => arr.findIndex((r) => r.key === row.key && r.slug === row.slug) === i)
    .sort((a, b) => b.alias.length - a.alias.length || a.alias.localeCompare(b.alias))
    .map((row) => Object.freeze(row)),
);

const BY_KEY = new Map();
for (const row of ALIAS_INDEX) if (!BY_KEY.has(row.key)) BY_KEY.set(row.key, row.slug);

/** Look up a concept by slug, term or alias (case-insensitive). Returns the concept or null. */
export function findConcept(slugOrTerm) {
  if (slugOrTerm == null) return null;
  const s = String(slugOrTerm);
  if (BY_SLUG.has(s)) return BY_SLUG.get(s);
  const k = norm(s);
  if (BY_SLUG.has(k)) return BY_SLUG.get(k);
  const slug = BY_KEY.get(k);
  return slug ? BY_SLUG.get(slug) : null;
}

// ══════════════════════════════════════════════════════════════════════════
// Assertions (run with plain node: node -e "import('./src/data/concepts-registry.js')...")
// ══════════════════════════════════════════════════════════════════════════
const KEBAB = /^[a-z0-9]+(?:-[a-z0-9]+)*$/;

export const CONCEPTS_REGISTRY_ASSERTIONS = Object.freeze([
  { name: 'slugs are unique', holds: () => BY_SLUG.size === CONCEPTS_REGISTRY.length },
  { name: 'slugs are kebab-case', holds: () => CONCEPTS_REGISTRY.every((x) => KEBAB.test(x.slug)) },
  { name: 'related slugs resolve and are not self-references',
    holds: () => CONCEPTS_REGISTRY.every((x) => x.related.every((r) => BY_SLUG.has(r) && r !== x.slug)) },
  { name: 'short is non-empty plain text of at most 160 characters',
    holds: () => CONCEPTS_REGISTRY.every((x) => typeof x.short === 'string' && x.short.length > 0 && x.short.length <= 160 && !/<\/?[a-z]/i.test(x.short)) },
  { name: 'aliases are non-empty arrays of non-empty strings',
    holds: () => CONCEPTS_REGISTRY.every((x) => x.aliases.length > 0 && x.aliases.every((a) => typeof a === 'string' && a.trim().length > 0)) },
  { name: 'no alias or term maps to two different concepts',
    holds: () => {
      const seen = new Map();
      for (const row of ALIAS_INDEX) {
        if (seen.has(row.key) && seen.get(row.key) !== row.slug) return false;
        seen.set(row.key, row.slug);
      }
      return true;
    } },
  { name: 'needsExposition is boolean', holds: () => CONCEPTS_REGISTRY.every((x) => typeof x.needsExposition === 'boolean') },
  { name: 'sources have a label and exactly one of path/route',
    holds: () => CONCEPTS_REGISTRY.every((x) => x.sources.every((s) => s.label && (('path' in s) !== ('route' in s)))) },
  { name: 'legacyRoute is null or starts with /',
    holds: () => CONCEPTS_REGISTRY.every((x) => x.legacyRoute === null || x.legacyRoute.startsWith('/')) },
  { name: 'no concept is an engine imp-NNNN headword',
    holds: () => CONCEPTS_REGISTRY.every((x) => !/imp-?\d/i.test(x.term) && !/imp-?\d/i.test(x.slug)) },
  { name: 'class slugs unique and kebab-case',
    holds: () => new Set(CONCEPT_CLASSES.map((k) => k.slug)).size === CONCEPT_CLASSES.length && CONCEPT_CLASSES.every((k) => KEBAB.test(k.slug)) },
  { name: 'class members resolve and are not duplicated within a class',
    holds: () => CONCEPT_CLASSES.every((k) => k.members.every((m) => BY_SLUG.has(m)) && new Set(k.members).size === k.members.length) },
  { name: 'relatedClasses resolve',
    holds: () => { const ks = new Set(CONCEPT_CLASSES.map((k) => k.slug)); return CONCEPT_CLASSES.every((k) => k.relatedClasses.every((r) => ks.has(r) && r !== k.slug)); } },
  { name: 'class short is at most 160 characters', holds: () => CONCEPT_CLASSES.every((k) => k.short.length <= 160) },
  { name: 'every concept belongs to at least one class', holds: () => CONCEPTS_REGISTRY.every((x) => x.classes.length >= 1) },
  { name: 'ALIAS_INDEX sorted longest-first', holds: () => ALIAS_INDEX.every((r, i) => i === 0 || ALIAS_INDEX[i - 1].alias.length >= r.alias.length) },
  { name: 'findConcept resolves slug, term and alias',
    holds: () => findConcept('theta-trap')?.slug === 'theta-trap'
      && findConcept('Θ-trap')?.slug === 'theta-trap'
      && findConcept('theta trap')?.slug === 'theta-trap'
      && findConcept('WOL-C')?.slug === 'weak-outer-lemma'
      && findConcept('de bruijn–newman constant λ')?.slug === 'de-bruijn-newman-constant'
      && findConcept('no such concept') === null },
  { name: 'required exposition concepts are present and flagged',
    holds: () => ['theta-trap', 'de-bruijn-newman-constant', 'heat-flow-ht', 'barrier-method', 'source-floor', 'kronecker-floor',
      'weak-outer-lemma', 'weil-positivity', 'twin-ladder', 'bridge-chi', 't3-strip', 'ns-rigid', 'flow-blindness', 'theorem-u',
      'route-vii-lane', 'platt-trudgian-verified-height', 'zero-free-region', 'arb-interval-certificate', 'davenport-heilbronn-twin',
      'levinsons-method', 'mirror-descent', 'decreasing-zero-height-barrier', 'two-band-lemma-b', 'local-rh-window',
      'structured-floor', 'prefix-and-cell'].every((s) => BY_SLUG.get(s)?.needsExposition === true) },
]);

for (const a of CONCEPTS_REGISTRY_ASSERTIONS) {
  if (!a.holds()) throw new Error(`concepts-registry assertion failed: ${a.name}`);
}
